class FinishReason:
    """
    Why a decode loop exited. Mirrors [`cera::FinishReason`].
"""
    def __init__(self):
        raise RuntimeError("FinishReason cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class MAX_TOKENS:
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "FinishReason.MAX_TOKENS()".format()
        def __eq__(self, other):
            if not isinstance(other, FinishReason):
                return NotImplemented
            if not other.is_MAX_TOKENS():
                return False
            return True

    @dataclass
    class STOP:
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "FinishReason.STOP()".format()
        def __eq__(self, other):
            if not isinstance(other, FinishReason):
                return NotImplemented
            if not other.is_STOP():
                return False
            return True

    @dataclass
    class CANCELLED:
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "FinishReason.CANCELLED()".format()
        def __eq__(self, other):
            if not isinstance(other, FinishReason):
                return NotImplemented
            if not other.is_CANCELLED():
                return False
            return True

    @dataclass
    class CONTEXT_FULL:
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "FinishReason.CONTEXT_FULL()".format()
        def __eq__(self, other):
            if not isinstance(other, FinishReason):
                return NotImplemented
            if not other.is_CONTEXT_FULL():
                return False
            return True

    @dataclass
    class GRAMMAR_DEAD_END:
        """
        A grammar constraint left no token allowed at this step — decoding
        stopped because the grammar dead-ended. Only reachable when
        `GenerateOpts.grammar` is set.
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "FinishReason.GRAMMAR_DEAD_END()".format()
        def __eq__(self, other):
            if not isinstance(other, FinishReason):
                return NotImplemented
            if not other.is_GRAMMAR_DEAD_END():
                return False
            return True

    @dataclass
    class ERROR:
        
        def __init__(self, message:str):
            self.message = message
            
            
            pass

    
            
            
    
        def __str__(self):
            return "FinishReason.ERROR(message={})".format(self.message)
        def __eq__(self, other):
            if not isinstance(other, FinishReason):
                return NotImplemented
            if not other.is_ERROR():
                return False
            if self.message != other.message:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_MAX_TOKENS(self) -> bool:
        return isinstance(self, FinishReason.MAX_TOKENS)
    def is_max_tokens(self) -> bool:
        return isinstance(self, FinishReason.MAX_TOKENS)
    def is_STOP(self) -> bool:
        return isinstance(self, FinishReason.STOP)
    def is_stop(self) -> bool:
        return isinstance(self, FinishReason.STOP)
    def is_CANCELLED(self) -> bool:
        return isinstance(self, FinishReason.CANCELLED)
    def is_cancelled(self) -> bool:
        return isinstance(self, FinishReason.CANCELLED)
    def is_CONTEXT_FULL(self) -> bool:
        return isinstance(self, FinishReason.CONTEXT_FULL)
    def is_context_full(self) -> bool:
        return isinstance(self, FinishReason.CONTEXT_FULL)
    def is_GRAMMAR_DEAD_END(self) -> bool:
        return isinstance(self, FinishReason.GRAMMAR_DEAD_END)
    def is_grammar_dead_end(self) -> bool:
        return isinstance(self, FinishReason.GRAMMAR_DEAD_END)
    def is_ERROR(self) -> bool:
        return isinstance(self, FinishReason.ERROR)
    def is_error(self) -> bool:
        return isinstance(self, FinishReason.ERROR)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
FinishReason.MAX_TOKENS = type("FinishReason.MAX_TOKENS", (FinishReason.MAX_TOKENS, FinishReason,), {})  # type: ignore
FinishReason.STOP = type("FinishReason.STOP", (FinishReason.STOP, FinishReason,), {})  # type: ignore
FinishReason.CANCELLED = type("FinishReason.CANCELLED", (FinishReason.CANCELLED, FinishReason,), {})  # type: ignore
FinishReason.CONTEXT_FULL = type("FinishReason.CONTEXT_FULL", (FinishReason.CONTEXT_FULL, FinishReason,), {})  # type: ignore
FinishReason.GRAMMAR_DEAD_END = type("FinishReason.GRAMMAR_DEAD_END", (FinishReason.GRAMMAR_DEAD_END, FinishReason,), {})  # type: ignore
FinishReason.ERROR = type("FinishReason.ERROR", (FinishReason.ERROR, FinishReason,), {})  # type: ignore




class _UniffiFfiConverterTypeFinishReason(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FinishReason.MAX_TOKENS(
            )
        if variant == 2:
            return FinishReason.STOP(
            )
        if variant == 3:
            return FinishReason.CANCELLED(
            )
        if variant == 4:
            return FinishReason.CONTEXT_FULL(
            )
        if variant == 5:
            return FinishReason.GRAMMAR_DEAD_END(
            )
        if variant == 6:
            return FinishReason.ERROR(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_MAX_TOKENS():
            return
        if value.is_STOP():
            return
        if value.is_CANCELLED():
            return
        if value.is_CONTEXT_FULL():
            return
        if value.is_GRAMMAR_DEAD_END():
            return
        if value.is_ERROR():
            _UniffiFfiConverterString.check_lower(value.message)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_MAX_TOKENS():
            buf.write_i32(1)
        if value.is_STOP():
            buf.write_i32(2)
        if value.is_CANCELLED():
            buf.write_i32(3)
        if value.is_CONTEXT_FULL():
            buf.write_i32(4)
        if value.is_GRAMMAR_DEAD_END():
            buf.write_i32(5)
        if value.is_ERROR():
            buf.write_i32(6)
            _UniffiFfiConverterString.write(value.message, buf)



